code.C:
#include <stdio.h>

int main() {
    long long a, b;
    char op;
    if (scanf("%lld %c %lld", &a, &op, &b) == 3) {
        if (op == '+') printf("%lld\n", a + b);
        else if (op == '-') printf("%lld\n", a - b);
        else if (op == '*') printf("%lld\n", a * b);
        else if (op == '/' && b != 0) printf("%lld\n", a / b);
    }
    return 0;
}

